window.__TNPSC_REGISTER_TEST__("maths", 8, [{"id":701,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 12 நாட்களிலும், B அதே வேலையை 24 நாட்களிலும் முடிப்பர் எனில், இருவரும் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["6 நாட்கள்","8 நாட்கள்","9 நாட்கள்","10 நாட்கள்"],"correctAnswer":1,"explanation":"சூத்திரம்: இருவரும் இணைந்து முடிக்கும் நாட்கள் = (A × B) / (A + B). இங்கு A = 12, B = 24. எனவே (12 × 24) / (12 + 24) = 288 / 36 = 8 நாட்கள்.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":702,"subject":"maths","testNumber":8,"question":"கவின் மற்றும் ரவி இணைந்து ஒரு வேலையை 6 நாட்களில் முடிப்பர். கவின் மட்டும் தனியே 15 நாட்களில் முடிப்பார் எனில், ரவி மட்டும் தனியே அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["8 நாட்கள்","9 நாட்கள்","10 நாட்கள்","12 நாட்கள்"],"correctAnswer":2,"explanation":"சூத்திரம்: B மட்டும் தனியே ஆகும் நாட்கள் = (AB × A) / (A - AB). ரவியின் 1 நாள் வேலை = 1/6 - 1/15 = (5 - 2)/30 = 3/30 = 1/10. எனவே ரவி மட்டும் தனியே 10 நாட்களில் முடிப்பார்.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":703,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையின் 1/4 பகுதியை 5 நாட்களிலும், B அதே வேலையின் 1/3 பகுதியை 10 நாட்களிலும் முடிப்பர் எனில், இருவரும் இணைந்து முழு வேலையையும் எத்தனை நாட்களில் முடிப்பர்?","options":["12 நாட்கள்","15 நாட்கள்","10 நாட்கள்","14 நாட்கள்"],"correctAnswer":0,"explanation":"A முழு வேலையை முடிக்கும் நாட்கள் = 5 × 4 = 20 நாட்கள். B முழு வேலையை முடிக்கும் நாட்கள் = 10 × 3 = 30 நாட்கள். இருவரும் இணைந்து முடிக்கும் நாட்கள் = (20 × 30) / (20 + 30) = 600 / 50 = 12 நாட்கள்.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":704,"subject":"maths","testNumber":8,"question":"A, B மற்றும் C ஆகிய மூவரும் தனித்தனியே ஒரு வேலையை முறையே 10, 12 மற்றும் 15 நாட்களில் முடிப்பர் எனில், மூவரும் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["3 நாட்கள்","5 நாட்கள்","6 நாட்கள்","4 நாட்கள்"],"correctAnswer":3,"explanation":"மூவரின் 1 நாள் வேலை = 1/10 + 1/12 + 1/15. மீ.சி.ம (10, 12, 15) = 60. எனவே (6 + 5 + 4)/60 = 15/60 = 1/4. ஆகவே மூவரும் இணைந்து 4 நாட்களில் முடிப்பர்.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":705,"subject":"maths","testNumber":8,"question":"A, B மற்றும் C மூவரும் இணைந்து ஒரு வேலையை 8 நாட்களில் முடிப்பர். A தனியே 20 நாட்களிலும், B தனியே 24 நாட்களிலும் முடிப்பர் எனில், C மட்டும் தனியே அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["25 நாட்கள்","30 நாட்கள்","36 நாட்கள்","40 நாட்கள்"],"correctAnswer":1,"explanation":"C-யின் 1 நாள் வேலை = 1/8 - (1/20 + 1/24). மீ.சி.ம (8, 20, 24) = 120. எனவே (15 - 6 - 5)/120 = 4/120 = 1/30. ஆகவே C மட்டும் தனியே 30 நாட்களில் முடிப்பார்.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":706,"subject":"maths","testNumber":8,"question":"A மற்றும் B இணைந்து ஒரு வேலையை 12 நாட்களிலும், B மற்றும் C இணைந்து 15 நாட்களிலும், C மற்றும் A இணைந்து 20 நாட்களிலும் முடிப்பர் எனில், A, B, C மூவரும் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["8 நாட்கள்","9 நாட்கள்","10 நாட்கள்","12 நாட்கள்"],"correctAnswer":2,"explanation":"2(A + B + C)-யின் 1 நாள் வேலை = 1/12 + 1/15 + 1/20 = (5 + 4 + 3)/60 = 12/60 = 1/5. எனவே (A + B + C)-யின் 1 நாள் வேலை = 1/10. ஆகவே மூவரும் இணைந்து 10 நாட்களில் முடிப்பர்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":707,"subject":"maths","testNumber":8,"question":"A மற்றும் B இணைந்து ஒரு வேலையை 10 நாட்களிலும், B மற்றும் C இணைந்து 15 நாட்களிலும், C மற்றும் A இணைந்து 12 நாட்களிலும் முடிப்பர் எனில், B மட்டும் தனியே அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["24 நாட்கள்","20 நாட்கள்","30 நாட்கள்","18 நாட்கள்"],"correctAnswer":0,"explanation":"2(A + B + C) = 1/10 + 1/15 + 1/12 = (6 + 4 + 5)/60 = 15/60 = 1/4. எனவே A + B + C = 1/8. B-யின் 1 நாள் வேலை = (A + B + C) - (C + A) = 1/8 - 1/12 = (3 - 2)/24 = 1/24. ஆகவே B தனியே 24 நாட்களில் முடிப்பார்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":708,"subject":"maths","testNumber":8,"question":"X மற்றும் Y இணைந்து ஒரு வேலையை 18 நாட்களிலும், Y மற்றும் Z இணைந்து 24 நாட்களிலும், Z மற்றும் X இணைந்து 36 நாட்களிலும் முடிப்பர் எனில், X மட்டும் தனியே அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["32 நாட்கள்","36 நாட்கள்","42 நாட்கள்","48 நாட்கள்"],"correctAnswer":3,"explanation":"2(X + Y + Z) = 1/18 + 1/24 + 1/36 = (4 + 3 + 2)/72 = 9/72 = 1/8. எனவே X + Y + Z = 1/16. X-யின் 1 நாள் வேலை = 1/16 - 1/24 = (3 - 2)/48 = 1/48. ஆகவே X தனியே 48 நாட்களில் முடிப்பார்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":709,"subject":"maths","testNumber":8,"question":"P ஒரு வேலையை 15 நாட்களிலும், Q அதே வேலையை 20 நாட்களிலும் முடிப்பர். இருவரும் இணைந்து 4 நாட்கள் வேலை செய்த பிறகு, மீதமுள்ள வேலையின் பகுதி எவ்வளவு?","options":["7/15","1/4","8/15","11/15"],"correctAnswer":2,"explanation":"P மற்றும் Q-வின் 1 நாள் வேலை = 1/15 + 1/20 = (4 + 3)/60 = 7/60. 4 நாட்களில் முடித்த வேலை = 4 × (7/60) = 28/60 = 7/15. மீதமுள்ள வேலை = 1 - 7/15 = 8/15.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":710,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 18 நாட்களிலும், B அதே வேலையை 15 நாட்களிலும் முடிப்பர். B தனியே 10 நாட்கள் வேலை செய்து விலகிய பின், மீதமுள்ள வேலையை A மட்டும் எத்தனை நாட்களில் முடிப்பார்?","options":["5 நாட்கள்","6 நாட்கள்","8 நாட்கள்","9 நாட்கள்"],"correctAnswer":1,"explanation":"B 10 நாட்களில் செய்த வேலை = 10/15 = 2/3 பங்கு. மீதமுள்ள வேலை = 1 - 2/3 = 1/3 பங்கு. 1 முழு வேலையை A 18 நாட்களில் முடிப்பார் என்பதால், 1/3 வேலையை முடிக்க ஆகும் நாட்கள் = (1/3) × 18 = 6 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":711,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 20 நாட்களிலும், B அதே வேலையை 30 நாட்களிலும் முடிப்பர். இருவரும் இணைந்து வேலையைத் தொடங்கி 6 நாட்கள் கழித்து A விலகினார் எனில், மீதமுள்ள வேலையை B மட்டும் எத்தனை நாட்களில் முடிப்பார்?","options":["15 நாட்கள்","12 நாட்கள்","18 நாட்கள்","10 நாட்கள்"],"correctAnswer":0,"explanation":"இருவரின் 1 நாள் வேலை = 1/20 + 1/30 = (3 + 2)/60 = 5/60 = 1/12. 6 நாட்களில் முடித்த வேலை = 6 × (1/12) = 1/2. மீதமுள்ள 1/2 வேலையை B முடிக்க ஆகும் நாட்கள் = (1/2) × 30 = 15 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":712,"subject":"maths","testNumber":8,"question":"அருண் ஒரு வேலையை 24 நாட்களிலும், பாலா 36 நாட்களிலும் முடிப்பர். இருவரும் இணைந்து வேலையைத் தொடங்கினர். வேலை முடிவதற்கு 6 நாட்களுக்கு முன் அருண் விலகினார் எனில், மொத்த வேலையும் எத்தனை நாட்களில் முடிந்தது?","options":["14 நாட்கள்","15 நாட்கள்","16 நாட்கள்","18 நாட்கள்"],"correctAnswer":3,"explanation":"மொத்த நாட்கள் = x என்க. அருண் (x - 6) நாட்களும், பாலா x நாட்களும் வேலை செய்தனர். எனவே (x - 6)/24 + x/36 = 1. மீ.சி.ம 72-ஆல் பெருக்க: 3(x - 6) + 2x = 72 ⇒ 5x - 18 = 72 ⇒ 5x = 90 ⇒ x = 18 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":713,"subject":"maths","testNumber":8,"question":"A, B மற்றும் C தனித்தனியே ஒரு வேலையை 10, 12 மற்றும் 15 நாட்களில் முடிப்பர். மூவரும் இணைந்து வேலையைத் தொடங்கினர். 2 நாட்கள் கழித்து A விலகினார்; வேலை முடிவதற்கு 3 நாட்கள் முன் B விலகினார் எனில், மொத்த வேலையும் எத்தனை நாட்களில் முடிந்தது?","options":["5 நாட்கள்","6 நாட்கள்","7 நாட்கள்","8 நாட்கள்"],"correctAnswer":2,"explanation":"மொத்த நாட்கள் = x என்க. A வேலை செய்தது 2 நாட்கள், B வேலை செய்தது (x - 3) நாட்கள், C வேலை செய்தது x நாட்கள். எனவே 2/10 + (x - 3)/12 + x/15 = 1. மீ.சி.ம 60-ஆல் பெருக்க: 12 + 5(x - 3) + 4x = 60 ⇒ 9x - 3 = 60 ⇒ 9x = 63 ⇒ x = 7 நாட்கள்.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":714,"subject":"maths","testNumber":8,"question":"A, B மற்றும் C முறையே 24, 30 மற்றும் 40 நாட்களில் ஒரு வேலையை முடிப்பர். மூவரும் இணைந்து வேலையைத் தொடங்கினர். ஆனால் வேலை முடிவதற்கு 4 நாட்கள் முன் C விலகினார் எனில், மொத்த வேலையும் எத்தனை நாட்களில் முடிந்தது?","options":["10 நாட்கள்","11 நாட்கள்","12 நாட்கள்","13 நாட்கள்"],"correctAnswer":1,"explanation":"மொத்த நாட்கள் = x என்க. A மற்றும் B முழு x நாட்களும், C (x - 4) நாட்களும் வேலை செய்தனர். எனவே x/24 + x/30 + (x - 4)/40 = 1. மீ.சி.ம 120-ஆல் பெருக்க: 5x + 4x + 3(x - 4) = 120 ⇒ 12x - 12 = 120 ⇒ 12x = 132 ⇒ x = 11 நாட்கள்.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":715,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 12 நாட்களிலும், B அதே வேலையை 16 நாட்களிலும் முடிப்பர். A முதல் நாள் தொடங்க, இருவரும் மாற்று நாட்களில் (ஒரு நாள் விட்டு ஒரு நாள்) வேலை செய்தால், அவ்வேலை எத்தனை நாட்களில் முடியும்?","options":["13 2/3 நாட்கள்","14 நாட்கள்","13 1/3 நாட்கள்","12 2/3 நாட்கள்"],"correctAnswer":0,"explanation":"மொத்த வேலை = மீ.சி.ம (12, 16) = 48 அலகுகள் என்க. A-யின் 1 நாள் வேலை = 4 அலகுகள், B-யின் 1 நாள் வேலை = 3 அலகுகள். 2 நாட்களில் முடியும் வேலை = 4 + 3 = 7 அலகுகள். 12 நாட்களில் (6 சுற்றுகள்) = 6 × 7 = 42 அலகுகள். 13-ஆம் நாள் A 4 அலகுகள் செய்ய, மொத்தம் 46 அலகுகள். மீதமுள்ள 2 அலகுகளை B முடிக்க 2/3 நாள் ஆகும். மொத்தம் = 13 2/3 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":716,"subject":"maths","testNumber":8,"question":"P ஒரு வேலையை 8 நாட்களிலும், Q அதே வேலையை 12 நாட்களிலும் முடிப்பர். P முதல் நாள் தொடங்க, இருவரும் மாற்று நாட்களில் வேலை செய்தால், அவ்வேலை எத்தனை நாட்களில் முடிவடையும்?","options":["9 நாட்கள்","10 நாட்கள்","8.5 நாட்கள்","9.5 நாட்கள்"],"correctAnswer":3,"explanation":"மொத்த வேலை = மீ.சி.ம (8, 12) = 24 அலகுகள் என்க. P = 3 அலகுகள்/நாள், Q = 2 அலகுகள்/நாள். 2 நாட்களில் = 5 அலகுகள். 8 நாட்களில் (4 சுற்றுகள்) = 20 அலகுகள். 9-ஆம் நாள் P 3 அலகுகள் முடித்தபின் 23 அலகுகள் நிறைவடையும். மீதமுள்ள 1 அலகை Q முடிக்க 1/2 = 0.5 நாள் ஆகும். மொத்தம் = 9.5 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":717,"subject":"maths","testNumber":8,"question":"A, B மற்றும் C முறையே 20, 30 மற்றும் 60 நாட்களில் ஒரு வேலையை முடிப்பர். A தினமும் வேலை செய்கிறார்; ஒவ்வொரு மூன்றாவது நாளிலும் B மற்றும் C ஆகியோர் A-க்கு உதவுகிறார்கள் எனில், அவ்வேலை எத்தனை நாட்களில் முடியும்?","options":["12 நாட்கள்","14 நாட்கள்","15 நாட்கள்","18 நாட்கள்"],"correctAnswer":2,"explanation":"மொத்த வேலை = மீ.சி.ம (20, 30, 60) = 60 அலகுகள் என்க. 1 நாள் வேலை: A = 3, B = 2, C = 1. 3 நாட்களில் முடியும் வேலை = A + A + (A + B + C) = 3 + 3 + 6 = 12 அலகுகள். எனவே 60 அலகுகளை முடிக்கத் தேவையான சுற்றுகள் = 60 / 12 = 5 சுற்றுகள். மொத்த நாட்கள் = 5 × 3 = 15 நாட்கள்.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":718,"subject":"maths","testNumber":8,"question":"A என்பவர் B-யை விட இரு மடங்கு திறமையானவர். இருவரும் இணைந்து ஒரு வேலையை 14 நாட்களில் முடிப்பர் எனில், A மட்டும் தனியே அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["18 நாட்கள்","21 நாட்கள்","28 நாட்கள்","42 நாட்கள்"],"correctAnswer":1,"explanation":"திறன் விகிதம் A : B = 2 : 1. இருவரின் மொத்த திறன் = 2 + 1 = 3 அலகுகள்/நாள். மொத்த வேலை = 3 × 14 = 42 அலகுகள். எனவே A மட்டும் தனியே முடிக்க ஆகும் நாட்கள் = 42 / 2 = 21 நாட்கள்.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":719,"subject":"maths","testNumber":8,"question":"செந்தில் என்பவர் முருகனை விட 3 மடங்கு வேகமாக வேலை செய்வார். எனவே ஒரு வேலையை முருகனை விட 40 நாட்கள் குறைவாகவே முடிப்பார். இருவரும் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["15 நாட்கள்","12 நாட்கள்","18 நாட்கள்","20 நாட்கள்"],"correctAnswer":0,"explanation":"திறன் விகிதம் செந்தில் : முருகன் = 3 : 1. எனவே கால விகிதம் = 1 : 3. வித்தியாசம் 2 பங்கு = 40 நாட்கள் ⇒ 1 பங்கு = 20 நாட்கள். ஆகவே செந்தில் = 20 நாட்கள், முருகன் = 60 நாட்கள். இருவரும் இணைந்து = (20 × 60) / (20 + 60) = 1200 / 80 = 15 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":720,"subject":"maths","testNumber":8,"question":"X என்பவர் Y-ஐ விட 25% அதிக திறன் கொண்டவர். Y மட்டும் ஒரு வேலையை 20 நாட்களில் முடிப்பார் எனில், X மட்டும் அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["12 நாட்கள்","14 நாட்கள்","15 நாட்கள்","16 நாட்கள்"],"correctAnswer":3,"explanation":"Y-யின் திறன் = 100 எனில், X-யின் திறன் = 125. திறன் விகிதம் X : Y = 5 : 4. வேலைக்கு ஆகும் காலம் திறனுக்கு எதிர் விகிதத்தில் இருக்கும். எனவே X-க்கு ஆகும் நாட்கள் = 20 × (4 / 5) = 16 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":721,"subject":"maths","testNumber":8,"question":"A என்பவர் B-யை விட 50% அதிக திறன் உடையவர். இருவரும் இணைந்து ஒரு வேலையை 12 நாட்களில் முடிப்பர் எனில், B மட்டும் தனியே அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["20 நாட்கள்","24 நாட்கள்","30 நாட்கள்","36 நாட்கள்"],"correctAnswer":2,"explanation":"திறன் விகிதம் A : B = 150 : 100 = 3 : 2. இருவரின் மொத்த திறன் = 3 + 2 = 5 அலகுகள். மொத்த வேலை = 5 × 12 = 60 அலகுகள். எனவே B மட்டும் தனியே முடிக்கும் நாட்கள் = 60 / 2 = 30 நாட்கள்.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":722,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 12 நாட்களில் முடிப்பார். B என்பவர் A-யை விட 60% அதிக திறன் உடையவர் எனில், B மட்டும் அவ்வேலையை எத்தனை நாட்களில் முடிப்பார்?","options":["6.5 நாட்கள்","7.5 நாட்கள்","8 நாட்கள்","8.5 நாட்கள்"],"correctAnswer":1,"explanation":"திறன் விகிதம் A : B = 100 : 160 = 5 : 8. மொத்த வேலை = A-யின் திறன் × நாட்கள் = 5 × 12 = 60 அலகுகள். எனவே B-க்கு ஆகும் நாட்கள் = 60 / 8 = 7.5 நாட்கள்.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":723,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 10 நாட்களிலும், B அதே வேலையை 15 நாட்களிலும் முடிப்பர். இருவரும் இணைந்து அவ்வேலையை முடித்து ₹1,500 ஊதியம் பெற்றால், A-யின் பங்கு எவ்வளவு?","options":["₹900","₹600","₹750","₹1,000"],"correctAnswer":0,"explanation":"ஊதியம் அவரவர் திறன் விகிதத்தில் பகிரப்படும். திறன் விகிதம் A : B = 1/10 : 1/15 = 3 : 2. மொத்த பங்குகள் = 5. எனவே A-யின் பங்கு = ₹1,500 × (3 / 5) = ₹900.","difficulty":"easy","topic":"நேரம் மற்றும் வேலை"},{"id":724,"subject":"maths","testNumber":8,"question":"A, B மற்றும் C மூவரும் தனித்தனியே ஒரு வேலையை 6, 8 மற்றும் 12 நாட்களில் முடிப்பர். மூவரும் இணைந்து வேலை செய்து ₹3,600 ஊதியம் பெற்றால், B-யின் பங்கு எவ்வளவு?","options":["₹800","₹1,000","₹1,600","₹1,200"],"correctAnswer":3,"explanation":"திறன் விகிதம் A : B : C = 1/6 : 1/8 : 1/12. மீ.சி.ம 24-ஆல் பெருக்க: 4 : 3 : 2. மொத்த பங்குகள் = 4 + 3 + 2 = 9. எனவே B-யின் பங்கு = ₹3,600 × (3 / 9) = ₹1,200.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":725,"subject":"maths","testNumber":8,"question":"A ஒரு வேலையை 6 நாட்களிலும், B அதே வேலையை 8 நாட்களிலும் முடிப்பர். C-யின் உதவியுடன் மூவரும் இணைந்து 3 நாட்களில் அவ்வேலையை முடித்து ₹3,200 ஊதியம் பெற்றால், C-க்குக் கிடைக்கும் ஊதியம் எவ்வளவு?","options":["₹600","₹800","₹400","₹1,200"],"correctAnswer":2,"explanation":"3 நாட்களில் A செய்த வேலை = 3/6 = 1/2. B செய்த வேலை = 3/8. எனவே C செய்த வேலை = 1 - (1/2 + 3/8) = 1 - 7/8 = 1/8 பங்கு. ஆகவே C-யின் ஊதியம் = ₹3,200 × (1/8) = ₹400.","difficulty":"medium","topic":"நேரம் மற்றும் வேலை"},{"id":726,"subject":"maths","testNumber":8,"question":"சுரேஷ் ஒரு வேலையை 10 நாட்களிலும், தினேஷ் 15 நாட்களிலும் முடிப்பர். இருவரும் 4 நாட்கள் இணைந்து வேலை செய்த பின், மீதமுள்ள வேலையை ரமேஷ் 2 நாட்களில் முடித்தார். மொத்த ஊதியம் ₹4,500 எனில், ரமேஷின் பங்கு எவ்வளவு?","options":["₹1,200","₹1,500","₹1,800","₹2,000"],"correctAnswer":1,"explanation":"சுரேஷ் மற்றும் தினேஷ் 4 நாட்களில் செய்த வேலை = 4 × (1/10 + 1/15) = 4 × (5/30) = 2/3 பங்கு. மீதமுள்ள 1 - 2/3 = 1/3 பங்கு வேலையை ரமேஷ் செய்தார். எனவே ரமேஷின் ஊதியம் = ₹4,500 × (1/3) = ₹1,500.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":727,"subject":"maths","testNumber":8,"question":"A மற்றும் B இணைந்து ஒரு வேலையை முடிக்க ஆகும் நாட்களை விட, A தனியே 4 நாட்கள் அதிகமாகவும், B தனியே 9 நாட்கள் அதிகமாகவும் எடுத்துக் கொள்வர் எனில், இருவரும் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["6 நாட்கள்","5 நாட்கள்","7 நாட்கள்","8 நாட்கள்"],"correctAnswer":0,"explanation":"சூத்திரம்: A தனியே (x + a) நாட்களிலும், B தனியே (x + b) நாட்களிலும் முடித்தால், இருவரும் இணைந்து முடிக்கும் நாட்கள் x = √(a × b). இங்கு a = 4, b = 9. எனவே x = √(4 × 9) = √36 = 6 நாட்கள்.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":728,"subject":"maths","testNumber":8,"question":"தட்டச்சர் A என்பவர் 6 மணி நேரத்தில் 32 பக்கங்களையும், B என்பவர் 5 மணி நேரத்தில் 40 பக்கங்களையும் தட்டச்சு செய்வர். இருவரும் தனித்தனி கணினிகளில் இணைந்து 110 பக்கங்களைத் தட்டச்சு செய்ய எவ்வளவு நேரம் ஆகும்?","options":["7 மணி 30 நிமிடங்கள்","8 மணி","8 மணி 30 நிமிடங்கள்","8 மணி 15 நிமிடங்கள்"],"correctAnswer":3,"explanation":"A-யின் 1 மணி நேர வேலை = 32/6 = 16/3 பக்கங்கள். B-யின் 1 மணி நேர வேலை = 40/5 = 8 பக்கங்கள். இருவரின் 1 மணி நேர வேலை = 16/3 + 8 = 40/3 பக்கங்கள். 110 பக்கங்களுக்கு ஆகும் நேரம் = 110 / (40/3) = 33/4 = 8¼ மணி = 8 மணி 15 நிமிடங்கள்.","difficulty":"hard","topic":"நேரம் மற்றும் வேலை"},{"id":729,"subject":"maths","testNumber":8,"question":"15 ஆட்கள் ஒரு வேலையை 24 நாட்களில் முடிப்பர் எனில், 18 ஆட்கள் அதே வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["16 நாட்கள்","18 நாட்கள்","20 நாட்கள்","22 நாட்கள்"],"correctAnswer":2,"explanation":"ஆட்கள் எண்ணிக்கையும் நாட்களும் எதிர் மாறலில் உள்ளன. சூத்திரம்: M₁ × D₁ = M₂ × D₂. எனவே 15 × 24 = 18 × D₂ ⇒ D₂ = 360 / 18 = 20 நாட்கள்.","difficulty":"easy","topic":"நேர் மற்றும் எதிர் மாறல்"},{"id":730,"subject":"maths","testNumber":8,"question":"12 தச்சர்கள் நாளொன்றுக்கு 6 மணி நேரம் வேலை செய்து 240 நாற்காலிகளை 15 நாட்களில் செய்கின்றனர். எனில் 18 தச்சர்கள் நாளொன்றுக்கு 8 மணி நேரம் வேலை செய்து 320 நாற்காலிகளை எத்தனை நாட்களில் செய்வர்?","options":["8 நாட்கள்","10 நாட்கள்","12 நாட்கள்","14 நாட்கள்"],"correctAnswer":1,"explanation":"சூத்திரம்: (M₁ × D₁ × H₁) / W₁ = (M₂ × D₂ × H₂) / W₂. இங்கு (12 × 15 × 6) / 240 = (18 × D₂ × 8) / 320 ⇒ 4.5 = (144 × D₂) / 320 ⇒ D₂ = (4.5 × 320) / 144 = 10 நாட்கள்.","difficulty":"easy","topic":"ஆள்-நாள்-மணி (Chain Rule)"},{"id":731,"subject":"maths","testNumber":8,"question":"ஒரு ராணுவ முகாமில் 400 வீரர்களுக்கு 31 நாட்களுக்குப் போதுமான உணவு இருந்தது. 28 நாட்கள் கழித்து 280 வீரர்கள் முகாமை விட்டுச் சென்றனர் எனில், மீதமுள்ள உணவு எஞ்சிய வீரர்களுக்கு எத்தனை நாட்களுக்குப் போதுமானதாக இருக்கும்?","options":["10 நாட்கள்","8 நாட்கள்","12 நாட்கள்","15 நாட்கள்"],"correctAnswer":0,"explanation":"28 நாட்களுக்குப் பிறகு, 400 வீரர்களுக்கு (31 - 28) = 3 நாட்களுக்கு உணவு மீதமுள்ளது. எஞ்சிய வீரர்கள் = 400 - 280 = 120. எதிர் மாறல் விதிப்படி: 400 × 3 = 120 × D ⇒ D = 1200 / 120 = 10 நாட்கள்.","difficulty":"easy","topic":"நேர் மற்றும் எதிர் மாறல்"},{"id":732,"subject":"maths","testNumber":8,"question":"ஒரு மாணவர் விடுதியில் 120 மாணவர்களுக்கு 45 நாட்களுக்குத் தேவையான உணவு உள்ளது. 15 நாட்கள் கழித்து மேலும் 30 மாணவர்கள் புதிதாகச் சேர்ந்தனர் எனில், மீதமுள்ள உணவு எத்தனை நாட்களுக்குப் போதுமானதாக இருக்கும்?","options":["18 நாட்கள்","20 நாட்கள்","22 நாட்கள்","24 நாட்கள்"],"correctAnswer":3,"explanation":"15 நாட்களுக்குப் பிறகு 120 மாணவர்களுக்கு (45 - 15) = 30 நாட்களுக்கு உணவு உள்ளது. புதிய மாணவர் எண்ணிக்கை = 120 + 30 = 150. எதிர் மாறல் விதிப்படி: 120 × 30 = 150 × D ⇒ D = 3600 / 150 = 24 நாட்கள்.","difficulty":"medium","topic":"நேர் மற்றும் எதிர் மாறல்"},{"id":733,"subject":"maths","testNumber":8,"question":"7 சிலந்திகள் 7 வலைகளை 7 நாட்களில் பின்னுகின்றன எனில், 1 சிலந்தி 1 வலையை எத்தனை நாட்களில் பின்னும்?","options":["1 நாள்","3 நாட்கள்","7 நாட்கள்","49 நாட்கள்"],"correctAnswer":2,"explanation":"சூத்திரம்: (M₁ × D₁) / W₁ = (M₂ × D₂) / W₂. இங்கு (7 × 7) / 7 = (1 × D₂) / 1 ⇒ D₂ = 7 நாட்கள். (ஒவ்வொரு சிலந்தியும் ஒரு வலையைப் பின்ன 7 நாட்கள் எடுத்துக் கொள்கிறது).","difficulty":"easy","topic":"ஆள்-நாள்-மணி (Chain Rule)"},{"id":734,"subject":"maths","testNumber":8,"question":"20 ஆட்கள் நாளொன்றுக்கு 9 மணி நேரம் வேலை செய்து 12 நாட்களில் 100 மீட்டர் நீளச் சுவரைக் கட்டுவர். எனில் 15 ஆட்கள் நாளொன்றுக்கு 6 மணி நேரம் வேலை செய்து 18 நாட்களில் எத்தனை மீட்டர் நீளச் சுவரைக் கட்டுவர்?","options":["60 மீ","75 மீ","80 மீ","90 மீ"],"correctAnswer":1,"explanation":"சூத்திரம்: (M₁ × D₁ × H₁) / W₁ = (M₂ × D₂ × H₂) / W₂. இங்கு (20 × 12 × 9) / 100 = (15 × 18 × 6) / W₂ ⇒ 2160 / 100 = 1620 / W₂ ⇒ W₂ = (1620 × 100) / 2160 = 75 மீ.","difficulty":"medium","topic":"ஆள்-நாள்-மணி (Chain Rule)"},{"id":735,"subject":"maths","testNumber":8,"question":"ஒரு ஒப்பந்ததாரர் ஒரு சாலையை 40 நாட்களில் முடிக்க 100 ஆட்களை நியமித்தார். 35 நாட்கள் கழித்து மேலும் 100 ஆட்களைச் சேர்த்ததால் வேலை சரியான நேரத்தில் முடிந்தது. கூடுதல் ஆட்களைச் சேர்க்காவிட்டால் வேலை எத்தனை நாட்கள் தாமதமாகியிருக்கும்?","options":["5 நாட்கள்","4 நாட்கள்","6 நாட்கள்","10 நாட்கள்"],"correctAnswer":0,"explanation":"கடைசி 5 நாட்களில் 200 ஆட்கள் செய்த வேலை = 200 × 5 = 1,000 ஆள்-நாட்கள். அதே வேலையை 100 ஆட்கள் மட்டும் செய்திருந்தால் ஆகும் நாட்கள் = 1,000 / 100 = 10 நாட்கள். எனவே தாமதம் = 10 - 5 = 5 நாட்கள்.","difficulty":"medium","topic":"ஆள்-நாள்-மணி (Chain Rule)"},{"id":736,"subject":"maths","testNumber":8,"question":"8 ஆண்கள் அல்லது 12 பெண்கள் ஒரு வேலையை 25 நாட்களில் முடிப்பர் எனில், 6 ஆண்கள் மற்றும் 11 பெண்கள் இணைந்து அதே வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["10 நாட்கள்","12 நாட்கள்","14 நாட்கள்","15 நாட்கள்"],"correctAnswer":3,"explanation":"8 ஆண்கள் = 12 பெண்கள் ⇒ 1 ஆண் = 3/2 பெண்கள். எனவே 6 ஆண்கள் + 11 பெண்கள் = 6 × (3/2) + 11 = 9 + 11 = 20 பெண்கள். 12 பெண்கள் 25 நாட்களில் முடிப்பர் எனில், 20 பெண்கள் முடிக்கும் நாட்கள் = (12 × 25) / 20 = 15 நாட்கள்.","difficulty":"medium","topic":"ஆண்கள்-பெண்கள்-சிறுவர்கள் வேலை"},{"id":737,"subject":"maths","testNumber":8,"question":"3 ஆண்கள் அல்லது 5 பெண்கள் ஒரு வேலையை 12 நாட்களில் முடிப்பர் எனில், 6 ஆண்கள் மற்றும் 5 பெண்கள் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["3 நாட்கள்","5 நாட்கள்","4 நாட்கள்","6 நாட்கள்"],"correctAnswer":2,"explanation":"3 ஆண்கள் = 5 பெண்கள் ⇒ 6 ஆண்கள் = 10 பெண்கள். எனவே 6 ஆண்கள் + 5 பெண்கள் = 10 + 5 = 15 பெண்கள். 5 பெண்கள் 12 நாட்களில் முடிப்பர் எனில், 15 பெண்கள் முடிக்கும் நாட்கள் = (5 × 12) / 15 = 4 நாட்கள்.","difficulty":"medium","topic":"ஆண்கள்-பெண்கள்-சிறுவர்கள் வேலை"},{"id":738,"subject":"maths","testNumber":8,"question":"4 ஆண்கள் மற்றும் 6 பெண்கள் இணைந்து ஒரு வேலையை 8 நாட்களில் முடிப்பர். 3 ஆண்கள் மற்றும் 7 பெண்கள் இணைந்து அதே வேலையை 10 நாட்களில் முடிப்பர் எனில், 10 பெண்கள் மட்டும் அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["32 நாட்கள்","40 நாட்கள்","36 நாட்கள்","45 நாட்கள்"],"correctAnswer":1,"explanation":"மொத்த வேலை சமம் என்பதால்: 8(4ஆ + 6பெ) = 10(3ஆ + 7பெ) ⇒ 32ஆ + 48பெ = 30ஆ + 70பெ ⇒ 2ஆ = 22பெ ⇒ 1 ஆண் = 11 பெண்கள். மொத்த வேலை = 8(4 × 11 + 6) = 8 × 50 = 400 பெண்-நாட்கள். எனவே 10 பெண்கள் முடிக்கும் நாட்கள் = 400 / 10 = 40 நாட்கள்.","difficulty":"hard","topic":"ஆண்கள்-பெண்கள்-சிறுவர்கள் வேலை"},{"id":739,"subject":"maths","testNumber":8,"question":"2 ஆண்கள் மற்றும் 3 சிறுவர்கள் ஒரு வேலையை 10 நாட்களிலும், 3 ஆண்கள் மற்றும் 2 சிறுவர்கள் அதே வேலையை 8 நாட்களிலும் முடிப்பர் எனில், 2 ஆண்கள் மற்றும் 1 சிறுவன் இணைந்து அவ்வேலையை எத்தனை நாட்களில் முடிப்பர்?","options":["12.5 நாட்கள்","10 நாட்கள்","12 நாட்கள்","14.5 நாட்கள்"],"correctAnswer":0,"explanation":"10(2ஆ + 3சி) = 8(3ஆ + 2சி) ⇒ 20ஆ + 30சி = 24ஆ + 16சி ⇒ 4ஆ = 14சி ⇒ 2ஆ = 7சி. மொத்த வேலை = 10(7சி + 3சி) = 100 சிறுவர்-நாட்கள். இப்போது 2ஆ + 1சி = 7சி + 1சி = 8 சிறுவர்கள். எனவே ஆகும் நாட்கள் = 100 / 8 = 12.5 நாட்கள்.","difficulty":"hard","topic":"ஆண்கள்-பெண்கள்-சிறுவர்கள் வேலை"},{"id":740,"subject":"maths","testNumber":8,"question":"14 நீர் இறைக்கும் பம்புகள் 6 மணி நேரத்தில் ஒரு தொட்டியை நிரப்புகின்றன. அதே தொட்டியை 4 மணி நேரத்தில் நிரப்ப மேலும் எத்தனை கூடுதல் பம்புகள் தேவை?","options":["21 பம்புகள்","10 பம்புகள்","5 பம்புகள்","7 பம்புகள்"],"correctAnswer":3,"explanation":"பம்புகளின் எண்ணிக்கையும் நேரமும் எதிர் மாறலில் உள்ளன. மொத்த தேவையான பம்புகள் = (14 × 6) / 4 = 21 பம்புகள். ஏற்கனவே 14 பம்புகள் உள்ளதால், கூடுதலாகத் தேவைப்படுபவை = 21 - 14 = 7 பம்புகள்.","difficulty":"easy","topic":"நேர் மற்றும் எதிர் மாறல்"},{"id":741,"subject":"maths","testNumber":8,"question":"6 இயந்திரங்கள் நிமிடத்திற்கு 270 பாட்டில்களைத் தயாரிக்கின்றன எனில், அதே திறனுடைய 10 இயந்திரங்கள் 4 நிமிடங்களில் எத்தனை பாட்டில்களைத் தயாரிக்கும்?","options":["1,500 பாட்டில்கள்","1,620 பாட்டில்கள்","1,800 பாட்டில்கள்","2,000 பாட்டில்கள்"],"correctAnswer":2,"explanation":"1 இயந்திரம் 1 நிமிடத்தில் தயாரிக்கும் பாட்டில்கள் = 270 / 6 = 45. எனவே 10 இயந்திரங்கள் 4 நிமிடங்களில் தயாரிக்கும் பாட்டில்கள் = 45 × 10 × 4 = 1,800 பாட்டில்கள்.","difficulty":"medium","topic":"ஆள்-நாள்-மணி (Chain Rule)"},{"id":742,"subject":"maths","testNumber":8,"question":"12 ஆண்கள் ஒரு வேலையை 9 நாட்களில் முடிப்பர். அவர்கள் 6 நாட்கள் வேலை செய்த பிறகு, மேலும் 6 ஆண்கள் அவர்களுடன் சேர்ந்தனர். மீதமுள்ள வேலையை அனைவரும் இணைந்து எத்தனை நாட்களில் முடிப்பர்?","options":["3 நாட்கள்","2 நாட்கள்","4 நாட்கள்","2.5 நாட்கள்"],"correctAnswer":1,"explanation":"6 நாட்களுக்குப் பிறகு மீதமுள்ள வேலை = 12 ஆண்கள் × (9 - 6) நாட்கள் = 36 ஆள்-நாட்கள். புதிய ஆட்கள் எண்ணிக்கை = 12 + 6 = 18. எனவே மீதமுள்ள வேலையை முடிக்க ஆகும் நாட்கள் = 36 / 18 = 2 நாட்கள்.","difficulty":"medium","topic":"ஆள்-நாள்-மணி (Chain Rule)"},{"id":743,"subject":"maths","testNumber":8,"question":"16 பெண்கள் ஒரு வேலையை 12 நாட்களில் முடிப்பர். 12 ஆண்கள் அதே வேலையை 8 நாட்களில் முடிப்பர். 16 ஆண்கள் வேலையைத் தொடங்கி 3 நாட்கள் கழித்து 10 ஆண்கள் விலகி, 4 பெண்கள் சேர்ந்தனர். மீதமுள்ள வேலையை முடிக்க எத்தனை நாட்கள் ஆகும்?","options":["6 நாட்கள்","5 நாட்கள்","8 நாட்கள்","4 நாட்கள்"],"correctAnswer":0,"explanation":"16பெ × 12 = 12ஆ × 8 ⇒ 192பெ = 96ஆ ⇒ 1 ஆண் = 2 பெண்கள். மொத்த வேலை = 192 பெண்-நாட்கள். 16 ஆண்கள் (= 32 பெண்கள்) 3 நாட்களில் செய்த வேலை = 32 × 3 = 96. மீதமுள்ள வேலை = 192 - 96 = 96. தற்போதைய பணியாளர்கள் = 6 ஆண்கள் + 4 பெண்கள் = 12 + 4 = 16 பெண்கள். ஆகவே ஆகும் நாட்கள் = 96 / 16 = 6 நாட்கள்.","difficulty":"hard","topic":"ஆண்கள்-பெண்கள்-சிறுவர்கள் வேலை"},{"id":744,"subject":"maths","testNumber":8,"question":"குழாய் A ஒரு தொட்டியை 15 நிமிடங்களிலும், குழாய் B 30 நிமிடங்களிலும் நிரப்பும். இரு குழாய்களும் ஒரே நேரத்தில் திறக்கப்பட்டால் தொட்டி எத்தனை நிமிடங்களில் நிரம்பும்?","options":["12 நிமிடங்கள்","15 நிமிடங்கள்","8 நிமிடங்கள்","10 நிமிடங்கள்"],"correctAnswer":3,"explanation":"சூத்திரம்: இரு குழாய்களும் சேர்ந்து நிரப்பும் நேரம் = (A × B) / (A + B). இங்கு (15 × 30) / (15 + 30) = 450 / 45 = 10 நிமிடங்கள்.","difficulty":"easy","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":745,"subject":"maths","testNumber":8,"question":"ஒரு குழாய் ஒரு தொட்டியை 6 மணி நேரத்தில் நிரப்பும்; மற்றொரு வெளியேற்றும் குழாய் நிரம்பிய தொட்டியை 10 மணி நேரத்தில் காலி செய்யும். இரு குழாய்களும் ஒரே நேரத்தில் திறக்கப்பட்டால் தொட்டி எத்தனை மணி நேரத்தில் நிரம்பும்?","options":["12 மணி","14 மணி","15 மணி","18 மணி"],"correctAnswer":2,"explanation":"1 மணி நேரத்தில் நிரம்பும் நிகரப் பகுதி = 1/6 - 1/10 = (5 - 3)/30 = 2/30 = 1/15. எனவே தொட்டி முழுவதும் நிரம்ப 15 மணி நேரம் ஆகும்.","difficulty":"easy","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":746,"subject":"maths","testNumber":8,"question":"மூன்று குழாய்கள் A, B மற்றும் C ஒரு தொட்டியைத் தனித்தனியே முறையே 12, 15 மற்றும் 20 மணி நேரத்தில் நிரப்பும். மூன்றும் ஒரே நேரத்தில் திறக்கப்பட்டால் தொட்டி எத்தனை மணி நேரத்தில் நிரம்பும்?","options":["4 மணி","5 மணி","6 மணி","8 மணி"],"correctAnswer":1,"explanation":"மூன்று குழாய்களின் 1 மணி நேர வேலை = 1/12 + 1/15 + 1/20 = (5 + 4 + 3)/60 = 12/60 = 1/5. எனவே தொட்டி 5 மணி நேரத்தில் நிரம்பும்.","difficulty":"easy","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":747,"subject":"maths","testNumber":8,"question":"ஒரு குழாய் ஒரு தொட்டியை 8 மணி நேரத்தில் நிரப்பும். ஆனால் தொட்டியின் அடியில் உள்ள கசிவு காரணமாக தொட்டி நிரம்ப 10 மணி நேரம் ஆகிறது. தொட்டி முழுமையாக நிரம்பிய நிலையில், அக்கசிவு மட்டும் தொட்டியை எத்தனை மணி நேரத்தில் காலி செய்யும்?","options":["40 மணி","32 மணி","36 மணி","45 மணி"],"correctAnswer":0,"explanation":"கசிவின் 1 மணி நேர வெளியேற்றம் = 1/8 - 1/10 = (5 - 4)/40 = 1/40. எனவே நிரம்பிய தொட்டியைக் கசிவு மட்டும் 40 மணி நேரத்தில் காலி செய்யும்.","difficulty":"medium","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":748,"subject":"maths","testNumber":8,"question":"A மற்றும் B குழாய்கள் ஒரு தொட்டியை முறையே 20 நிமிடங்கள் மற்றும் 30 நிமிடங்களில் நிரப்பும். இரு குழாய்களும் திறக்கப்பட்டு 8 நிமிடங்கள் கழித்து A மூடப்படுகிறது எனில், மீதமுள்ள தொட்டியை B எத்தனை நிமிடங்களில் நிரப்பும்?","options":["6 நிமிடங்கள்","8 நிமிடங்கள்","12 நிமிடங்கள்","10 நிமிடங்கள்"],"correctAnswer":3,"explanation":"இரு குழாய்களும் 8 நிமிடங்களில் நிரப்பிய பகுதி = 8 × (1/20 + 1/30) = 8 × (5/60) = 2/3. மீதமுள்ள பகுதி = 1 - 2/3 = 1/3. இதை B நிரப்ப ஆகும் நேரம் = (1/3) × 30 = 10 நிமிடங்கள்.","difficulty":"medium","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":749,"subject":"maths","testNumber":8,"question":"A மற்றும் B குழாய்கள் ஒரு தொட்டியை 12 மற்றும் 18 நிமிடங்களில் நிரப்பும்; C குழாய் நிரம்பிய தொட்டியை 36 நிமிடங்களில் காலி செய்யும். மூன்றும் ஒரே நேரத்தில் திறக்கப்பட்டால் தொட்டி எத்தனை நிமிடங்களில் நிரம்பும்?","options":["6 நிமிடங்கள்","8 நிமிடங்கள்","9 நிமிடங்கள்","12 நிமிடங்கள்"],"correctAnswer":2,"explanation":"1 நிமிடத்தில் நிரம்பும் நிகரப் பகுதி = 1/12 + 1/18 - 1/36 = (3 + 2 - 1)/36 = 4/36 = 1/9. எனவே தொட்டி 9 நிமிடங்களில் நிரம்பும்.","difficulty":"medium","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":750,"subject":"maths","testNumber":8,"question":"ஒரு மின்பம்பு ஒரு தொட்டியை 2 மணி நேரத்தில் நிரப்பும். தொட்டியில் உள்ள கசிவினால் தொட்டி நிரம்ப 2 மணி 20 நிமிடங்கள் ஆனது எனில், நிரம்பிய தொட்டியைக் கசிவு மட்டும் எத்தனை மணி நேரத்தில் காலி செய்யும்?","options":["12 மணி","14 மணி","16 மணி","10 மணி"],"correctAnswer":1,"explanation":"2 மணி 20 நிமிடங்கள் = 2⅓ மணி = 7/3 மணி. கசிவின் 1 மணி நேர வெளியேற்றம் = 1/2 - 3/7 = (7 - 6)/14 = 1/14. எனவே கசிவு மட்டும் தொட்டியை 14 மணி நேரத்தில் காலி செய்யும்.","difficulty":"medium","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":751,"subject":"maths","testNumber":8,"question":"A மற்றும் B குழாய்கள் ஒரு தொட்டியை முறையே 15 மணி மற்றும் 20 மணி நேரத்தில் நிரப்பும்; C குழாய் நிரம்பிய தொட்டியை 25 மணி நேரத்தில் காலி செய்யும். மூன்றும் திறக்கப்பட்டு 10 மணி நேரம் கழித்து C மூடப்படுகிறது எனில், தொட்டி முழுவதும் நிரம்ப மொத்தம் எவ்வளவு நேரம் ஆகும்?","options":["12 மணி","10 மணி","14 மணி","15 மணி"],"correctAnswer":0,"explanation":"10 மணி நேரத்தில் மூன்றும் சேர்ந்து நிரப்பிய பகுதி = 10 × (1/15 + 1/20 - 1/25) = 10 × (20 + 15 - 12)/300 = 230/300 = 23/30. மீதமுள்ள பகுதி = 1 - 23/30 = 7/30. A மற்றும் B-யின் 1 மணி நேர வேலை = 1/15 + 1/20 = 7/60. மீதத்தை நிரப்ப ஆகும் நேரம் = (7/30) ÷ (7/60) = 2 மணி. மொத்த நேரம் = 10 + 2 = 12 மணி.","difficulty":"hard","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":752,"subject":"maths","testNumber":8,"question":"ஒரு குழாய் ஒரு தொட்டியை 16 நிமிடங்களில் நிரப்பும்; மற்றொரு குழாய் 8 நிமிடங்களில் காலி செய்யும். தொட்டி ஏற்கனவே 3/4 பகுதி நிரம்பிய நிலையில் இரு குழாய்களும் திறக்கப்பட்டால், தொட்டி எத்தனை நிமிடங்களில் காலியாகும்?","options":["8 நிமிடங்கள்","10 நிமிடங்கள்","16 நிமிடங்கள்","12 நிமிடங்கள்"],"correctAnswer":3,"explanation":"1 நிமிடத்தில் காலியாகும் நிகரப் பகுதி = 1/8 - 1/16 = (2 - 1)/16 = 1/16. ஏற்கனவே உள்ள 3/4 பகுதி நீர் காலியாக ஆகும் நேரம் = (3/4) ÷ (1/16) = (3/4) × 16 = 12 நிமிடங்கள்.","difficulty":"medium","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":753,"subject":"maths","testNumber":8,"question":"இரு குழாய்கள் A மற்றும் B ஒரு தொட்டியை 20 மற்றும் 24 நிமிடங்களில் நிரப்பும். ஒரு வெளியேற்றும் குழாய் C நிமிடத்திற்கு 3 கேலன் நீரை வெளியேற்றும். மூன்று குழாய்களும் ஒன்றாகத் திறக்கப்பட்டால் தொட்டி 15 நிமிடங்களில் நிரம்பும் எனில், தொட்டியின் கொள்ளளவு எத்தனை கேலன்கள்?","options":["90 கேலன்கள்","100 கேலன்கள்","120 கேலன்கள்","150 கேலன்கள்"],"correctAnswer":2,"explanation":"வெளியேற்றும் குழாய் C-யின் 1 நிமிட வேலை = (1/20 + 1/24) - 1/15 = (6 + 5 - 8)/120 = 3/120 = 1/40. எனவே C மட்டும் 40 நிமிடங்களில் தொட்டியைக் காலி செய்யும். நிமிடத்திற்கு 3 கேலன் என்பதால், தொட்டியின் கொள்ளளவு = 40 × 3 = 120 கேலன்கள்.","difficulty":"hard","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":754,"subject":"maths","testNumber":8,"question":"குழாய் A ஒரு தொட்டியை 12 மணி நேரத்திலும், குழாய் B 16 மணி நேரத்திலும் நிரப்பும். இரு குழாய்களும் திறக்கப்பட்டு, தொட்டி சரியாக 9 மணி நேரத்தில் நிரம்ப எத்தனை மணி நேரம் கழித்து குழாய் B மூடப்பட வேண்டும்?","options":["3 மணி","4 மணி","5 மணி","6 மணி"],"correctAnswer":1,"explanation":"குழாய் A முழு 9 மணி நேரமும் திறந்திருக்கும். 9 மணி நேரத்தில் A நிரப்பிய பகுதி = 9/12 = 3/4. மீதமுள்ள 1 - 3/4 = 1/4 பகுதியை B நிரப்ப வேண்டும். B நிரப்ப ஆகும் நேரம் = (1/4) × 16 = 4 மணி. எனவே 4 மணி நேரம் கழித்து B மூடப்பட வேண்டும்.","difficulty":"medium","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":755,"subject":"maths","testNumber":8,"question":"குழாய் A ஒரு தொட்டியை 4 மணி நேரத்திலும், குழாய் B 6 மணி நேரத்திலும் நிரப்பும். குழாய் A முதலாவதாகத் திறக்கப்பட்டு, ஒவ்வொரு மணி நேரமும் மாறி மாறி (A, பின் B) திறக்கப்பட்டால் தொட்டி எவ்வளவு நேரத்தில் நிரம்பும்?","options":["4 மணி 40 நிமிடங்கள்","4 மணி 30 நிமிடங்கள்","5 மணி","4 மணி 20 நிமிடங்கள்"],"correctAnswer":0,"explanation":"தொட்டியின் கொள்ளளவு = மீ.சி.ம (4, 6) = 12 அலகுகள் என்க. A = 3 அலகுகள்/மணி, B = 2 அலகுகள்/மணி. 2 மணி நேரத்தில் = 5 அலகுகள். 4 மணி நேரத்தில் = 10 அலகுகள். மீதமுள்ள 2 அலகுகளை 5-ஆம் மணி நேரத்தில் A நிரப்ப ஆகும் நேரம் = (2/3) மணி = 40 நிமிடங்கள். மொத்த நேரம் = 4 மணி 40 நிமிடங்கள்.","difficulty":"hard","topic":"குழாய்கள் மற்றும் தொட்டிகள்"},{"id":756,"subject":"maths","testNumber":8,"question":"72 கி.மீ/மணி என்ற வேகத்தை மீ/வினாடியாக மாற்றுக.","options":["15 மீ/வினாடி","18 மீ/வினாடி","25 மீ/வினாடி","20 மீ/வினாடி"],"correctAnswer":3,"explanation":"சூத்திரம்: கி.மீ/மணியை மீ/வினாடியாக மாற்ற 5/18-ஆல் பெருக்க வேண்டும். எனவே 72 × (5 / 18) = 4 × 5 = 20 மீ/வினாடி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":757,"subject":"maths","testNumber":8,"question":"25 மீ/வினாடி என்ற வேகத்தை கி.மீ/மணியாக மாற்றுக.","options":["75 கி.மீ/மணி","80 கி.மீ/மணி","90 கி.மீ/மணி","100 கி.மீ/மணி"],"correctAnswer":2,"explanation":"சூத்திரம்: மீ/வினாடியை கி.மீ/மணியாக மாற்ற 18/5-ஆல் பெருக்க வேண்டும். எனவே 25 × (18 / 5) = 5 × 18 = 90 கி.மீ/மணி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":758,"subject":"maths","testNumber":8,"question":"ஒரு கார் 45 கி.மீ/மணி என்ற சீரான வேகத்தில் 4 மணி 20 நிமிடங்கள் பயணம் செய்தால், அது கடந்த மொத்த தூரம் எவ்வளவு?","options":["180 கி.மீ","195 கி.மீ","200 கி.மீ","210 கி.மீ"],"correctAnswer":1,"explanation":"நேரம் = 4 மணி 20 நிமிடங்கள் = 4⅓ மணி = 13/3 மணி. சூத்திரம்: தூரம் = வேகம் × நேரம் = 45 × (13 / 3) = 15 × 13 = 195 கி.மீ.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":759,"subject":"maths","testNumber":8,"question":"ஒரு மிதிவண்டி ஓட்டுநர் 750 மீட்டர் தூரத்தை 2 நிமிடம் 30 வினாடிகளில் கடக்கிறார் எனில், அவரின் வேகம் கி.மீ/மணியில் எவ்வளவு?","options":["18 கி.மீ/மணி","15 கி.மீ/மணி","20 கி.மீ/மணி","24 கி.மீ/மணி"],"correctAnswer":0,"explanation":"நேரம் = 2 நிமிடம் 30 வினாடிகள் = 150 வினாடிகள். வேகம் = தூரம் / நேரம் = 750 / 150 = 5 மீ/வினாடி. இதை கி.மீ/மணியாக மாற்ற: 5 × (18 / 5) = 18 கி.மீ/மணி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":760,"subject":"maths","testNumber":8,"question":"ஒரு நபர் A நகரத்திலிருந்து B நகரத்திற்கு 40 கி.மீ/மணி வேகத்திலும், B-யிலிருந்து A-க்கு 60 கி.மீ/மணி வேகத்திலும் திரும்புகிறார் எனில், முழுப் பயணத்தின் சராசரி வேகம் எவ்வளவு?","options":["50 கி.மீ/மணி","45 கி.மீ/மணி","52 கி.மீ/மணி","48 கி.மீ/மணி"],"correctAnswer":3,"explanation":"சம தூரத்திற்குச் சராசரி வேகச் சூத்திரம் = 2xy / (x + y). இங்கு x = 40, y = 60. எனவே (2 × 40 × 60) / (40 + 60) = 4800 / 100 = 48 கி.மீ/மணி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":761,"subject":"maths","testNumber":8,"question":"ஒரு மோட்டார் சைக்கிள் முதல் 120 கி.மீ தூரத்தை 60 கி.மீ/மணி வேகத்திலும், அடுத்த 180 கி.மீ தூரத்தை 45 கி.மீ/மணி வேகத்திலும் கடக்கிறது எனில், மொத்தப் பயணத்தின் சராசரி வேகம் எவ்வளவு?","options":["48 கி.மீ/மணி","52.5 கி.மீ/மணி","50 கி.மீ/மணி","55 கி.மீ/மணி"],"correctAnswer":2,"explanation":"சராசரி வேகம் = மொத்த தூரம் / மொத்த நேரம். மொத்த தூரம் = 120 + 180 = 300 கி.மீ. மொத்த நேரம் = (120/60) + (180/45) = 2 + 4 = 6 மணி. எனவே சராசரி வேகம் = 300 / 6 = 50 கி.மீ/மணி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":762,"subject":"maths","testNumber":8,"question":"ஒரு கார் ஒரு குறிப்பிட்ட தூரத்தின் முதல் பாதியை 30 கி.மீ/மணி வேகத்திலும், மீதிப் பாதியை 60 கி.மீ/மணி வேகத்திலும் கடந்து மொத்தம் 6 மணி நேரம் எடுத்துக் கொண்டால், கடந்த மொத்த தூரம் எவ்வளவு?","options":["200 கி.மீ","240 கி.மீ","270 கி.மீ","300 கி.மீ"],"correctAnswer":1,"explanation":"இரு சம பாதிகளுக்கான சராசரி வேகம் = (2 × 30 × 60) / (30 + 60) = 3600 / 90 = 40 கி.மீ/மணி. மொத்த நேரம் = 6 மணி. எனவே மொத்த தூரம் = 40 × 6 = 240 கி.மீ.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":763,"subject":"maths","testNumber":8,"question":"ஒரு நபர் மூன்று சம தூரங்களை முறையே 10 கி.மீ/மணி, 20 கி.மீ/மணி மற்றும் 60 கி.மீ/மணி வேகங்களில் கடக்கிறார் எனில், அவரது முழுப் பயணத்தின் சராசரி வேகம் எவ்வளவு?","options":["18 கி.மீ/மணி","20 கி.மீ/மணி","24 கி.மீ/மணி","30 கி.மீ/மணி"],"correctAnswer":0,"explanation":"ஒவ்வொரு சம தூரமும் 60 கி.மீ என்க. மொத்த தூரம் = 3 × 60 = 180 கி.மீ. மொத்த நேரம் = 60/10 + 60/20 + 60/60 = 6 + 3 + 1 = 10 மணி. சராசரி வேகம் = 180 / 10 = 18 கி.மீ/மணி.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":764,"subject":"maths","testNumber":8,"question":"ஒரு மாணவன் மணிக்கு 4 கி.மீ வேகத்தில் பள்ளிக்குச் சென்றால் 5 நிமிடம் தாமதமாகவும், மணிக்கு 5 கி.மீ வேகத்தில் சென்றால் 10 நிமிடம் முன்கூட்டியேயும் செல்கிறான் எனில், வீட்டிற்கும் பள்ளிக்கும் இடையேயான தூரம் எவ்வளவு?","options":["4 கி.மீ","6 கி.மீ","8 கி.மீ","5 கி.மீ"],"correctAnswer":3,"explanation":"சூத்திரம்: தூரம் = [ (S₁ × S₂) / (S₂ - S₁) ] × நேர வித்தியாசம் (மணியில்). நேர வித்தியாசம் = 5 + 10 = 15 நிமிடங்கள் = 15/60 = 1/4 மணி. எனவே தூரம் = [ (4 × 5) / (5 - 4) ] × (1/4) = 20 × (1/4) = 5 கி.மீ.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":765,"subject":"maths","testNumber":8,"question":"ஒரு அலுவலர் தனது வழக்கமான வேகத்தில் 3/4 பங்கு வேகத்தில் அலுவலகம் சென்றதால் 20 நிமிடங்கள் தாமதமாகச் சென்றடைந்தார். அவர் வழக்கமாக எடுத்துக் கொள்ளும் பயண நேரம் எவ்வளவு?","options":["45 நிமிடங்கள்","50 நிமிடங்கள்","60 நிமிடங்கள்","80 நிமிடங்கள்"],"correctAnswer":2,"explanation":"வேகம் 3/4 பங்காகக் குறைந்தால், நேரம் 4/3 பங்காக அதிகரிக்கும். கூடுதல் நேரம் = (4/3 - 1) × வழக்கமான நேரம் = (1/3) × T = 20 நிமிடங்கள். எனவே வழக்கமான நேரம் T = 20 × 3 = 60 நிமிடங்கள்.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":766,"subject":"maths","testNumber":8,"question":"ஒருவர் தனது வழக்கமான வேகத்தில் 5/4 பங்கு வேகத்தில் நடந்தால் 15 நிமிடங்கள் முன்கூட்டியே இலக்கை அடைவார் எனில், அவரது வழக்கமான பயண நேரம் எவ்வளவு?","options":["60 நிமிடங்கள்","75 நிமிடங்கள்","80 நிமிடங்கள்","90 நிமிடங்கள்"],"correctAnswer":1,"explanation":"வேகம் 5/4 பங்காக அதிகரித்தால், நேரம் 4/5 பங்காகக் குறையும். மிச்சமாகும் நேரம் = (1 - 4/5) × T = (1/5) × T = 15 நிமிடங்கள். எனவே வழக்கமான நேரம் T = 15 × 5 = 75 நிமிடங்கள்.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":767,"subject":"maths","testNumber":8,"question":"ஒரு திருடன் 200 மீட்டர் தொலைவில் இருக்கும் காவலரைப் பார்த்து மணிக்கு 10 கி.மீ வேகத்தில் ஓடுகிறான். உடனே காவலர் மணிக்கு 12 கி.மீ வேகத்தில் துரத்துகிறார் எனில், காவலர் திருடனை எத்தனை நிமிடங்களில் பிடிப்பார்?","options":["6 நிமிடங்கள்","5 நிமிடங்கள்","8 நிமிடங்கள்","10 நிமிடங்கள்"],"correctAnswer":0,"explanation":"ஒரே திசையில் சார்பு வேகம் = 12 - 10 = 2 கி.மீ/மணி = 2000 மீ / 60 நிமிடம் = 100/3 மீ/நிமிடம். காவலர் பிடிக்க ஆகும் நேரம் = தூரம் / சார்பு வேகம் = 200 ÷ (100/3) = 200 × (3/100) = 6 நிமிடங்கள்.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":768,"subject":"maths","testNumber":8,"question":"ஒரு திருடன் மதியம் 2:30 மணிக்கு ஒரு காரைத் திருடி மணிக்கு 60 கி.மீ வேகத்தில் ஓட்டிச் செல்கிறான். மாலை 3:00 மணிக்குத் திருட்டு தெரியவர, உரிமையாளர் மற்றொரு காரில் மணிக்கு 75 கி.மீ வேகத்தில் துரத்துகிறார் எனில், எத்தனை மணிக்குத் திருடனைப் பிடிப்பார்?","options":["மாலை 4:30 மணி","மாலை 5:30 மணி","மாலை 6:00 மணி","மாலை 5:00 மணி"],"correctAnswer":3,"explanation":"மதியம் 2:30 முதல் 3:00 வரை (½ மணி நேரத்தில்) திருடன் சென்ற தூரம் = 60 × ½ = 30 கி.மீ. சார்பு வேகம் = 75 - 60 = 15 கி.மீ/மணி. பிடிக்க ஆகும் நேரம் = 30 / 15 = 2 மணி நேரம். எனவே மாலை 3:00 + 2 மணி = மாலை 5:00 மணிக்குப் பிடிப்பார்.","difficulty":"hard","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":769,"subject":"maths","testNumber":8,"question":"ஒரு திருடன் காவலரிடமிருந்து 400 மீட்டர் தொலைவில் உள்ளான். திருடன் 8 கி.மீ/மணி வேகத்திலும், காவலர் 10 கி.மீ/மணி வேகத்திலும் ஒரே திசையில் ஓடினால், காவலர் திருடனைப் பிடிப்பதற்குள் திருடன் ஓடிய தூரம் எவ்வளவு?","options":["1.2 கி.மீ","2 கி.மீ","1.6 கி.மீ","1.8 கி.மீ"],"correctAnswer":2,"explanation":"இடைப்பட்ட தூரம் = 400 மீ = 0.4 கி.மீ. சார்பு வேகம் = 10 - 8 = 2 கி.மீ/மணி. பிடிக்க ஆகும் நேரம் = 0.4 / 2 = 0.2 மணி. அந்த நேரத்தில் திருடன் ஓடிய தூரம் = 8 × 0.2 = 1.6 கி.மீ.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":770,"subject":"maths","testNumber":8,"question":"A மற்றும் B என்ற இரு நகரங்களுக்கு இடையேயான தூரம் 330 கி.மீ. காலை 8 மணிக்கு A-யிலிருந்து ஒரு பேருந்து 60 கி.மீ/மணி வேகத்திலும், அதே நேரத்தில் B-யிலிருந்து மற்றொரு பேருந்து 50 கி.மீ/மணி வேகத்திலும் எதிரெதிர் திசையில் புறப்படுகின்றன எனில், அவை எத்தனை மணி நேரம் கழித்துச் சந்திக்கும்?","options":["2.5 மணி","3 மணி","3.5 மணி","4 மணி"],"correctAnswer":1,"explanation":"எதிரெதிர் திசையில் செல்லும் போது சார்பு வேகம் = 60 + 50 = 110 கி.மீ/மணி. சந்திக்கும் நேரம் = மொத்த தூரம் / சார்பு வேகம் = 330 / 110 = 3 மணி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":771,"subject":"maths","testNumber":8,"question":"A மற்றும் B நகரங்களுக்கு இடைப்பட்ட தூரம் 420 கி.மீ. ஒரு கார் A-யிலிருந்து காலை 7:00 மணிக்கு 60 கி.மீ/மணி வேகத்தில் புறப்படுகிறது. மற்றொரு கார் B-யிலிருந்து காலை 8:00 மணிக்கு 60 கி.மீ/மணி வேகத்தில் A-யை நோக்கிப் புறப்படுகிறது எனில், இரு கார்களும் எத்தனை மணிக்குச் சந்திக்கும்?","options":["காலை 11:00 மணி","காலை 10:30 மணி","காலை 11:30 மணி","மதியம் 12:00 மணி"],"correctAnswer":0,"explanation":"காலை 7:00 முதல் 8:00 வரை முதல் கார் கடந்த தூரம் = 60 கி.மீ. காலை 8:00 மணிக்கு மீதமுள்ள தூரம் = 420 - 60 = 360 கி.மீ. எதிரெதிர் சார்பு வேகம் = 60 + 60 = 120 கி.மீ/மணி. சந்திக்கும் நேரம் = 360 / 120 = 3 மணி. எனவே காலை 8:00 + 3 மணி = காலை 11:00 மணி.","difficulty":"medium","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":772,"subject":"maths","testNumber":8,"question":"ஒரு பேருந்து நிறுத்தங்கள் இன்றிச் சென்றால் அதன் சராசரி வேகம் 54 கி.மீ/மணி; நிறுத்தங்களுடன் சென்றால் அதன் சராசரி வேகம் 45 கி.மீ/மணி எனில், அப்பேருந்து ஒரு மணி நேரத்திற்குச் சராசரியாக எத்தனை நிமிடங்கள் நிற்கிறது?","options":["8 நிமிடங்கள்","9 நிமிடங்கள்","12 நிமிடங்கள்","10 நிமிடங்கள்"],"correctAnswer":3,"explanation":"சூத்திரம்: ஒரு மணி நேரத்திற்கு நிற்கும் நேரம் = [ (நிறுத்தமில்லா வேகம் - நிறுத்த வேகம்) / நிறுத்தமில்லா வேகம் ] × 60 நிமிடங்கள். இங்கு [ (54 - 45) / 54 ] × 60 = (9 / 54) × 60 = (1 / 6) × 60 = 10 நிமிடங்கள்.","difficulty":"hard","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":773,"subject":"maths","testNumber":8,"question":"இரு மிதிவண்டி ஓட்டுநர்கள் ஒரே இடத்திலிருந்து ஒரே திசையில் முறையே 12 கி.மீ/மணி மற்றும் 16 கி.மீ/மணி வேகத்தில் செல்கின்றனர். எத்தனை மணி நேரத்திற்குப் பிறகு அவர்களுக்கு இடையேயான தூரம் 28 கி.மீ ஆக இருக்கும்?","options":["5 மணி","6 மணி","7 மணி","8 மணி"],"correctAnswer":2,"explanation":"ஒரே திசையில் சார்பு வேகம் = 16 - 12 = 4 கி.மீ/மணி. அவர்களுக்கு இடையேயான தூரம் 28 கி.மீ ஆக ஆகும் நேரம் = 28 / 4 = 7 மணி.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":774,"subject":"maths","testNumber":8,"question":"ஒரு விமானம் 600 கி.மீ தூரத்தைக் கடக்கையில் மோசமான வானிலையால் அதன் சராசரி வேகம் 200 கி.மீ/மணி குறைந்ததால், பயண நேரம் 30 நிமிடங்கள் அதிகரித்தது. விமானத்தின் வழக்கமான பயண நேரம் எவ்வளவு?","options":["1.5 மணி","1 மணி","2 மணி","2.5 மணி"],"correctAnswer":1,"explanation":"வழக்கமான வேகம் = v கி.மீ/மணி என்க. 600/(v - 200) - 600/v = 1/2. சுருக்க: 600 × 200 / [v(v - 200)] = 1/2 ⇒ v(v - 200) = 240000 ⇒ v = 600 கி.மீ/மணி. எனவே வழக்கமான பயண நேரம் = 600 / 600 = 1 மணி.","difficulty":"hard","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":775,"subject":"maths","testNumber":8,"question":"A மற்றும் B ஆகியோரின் வேகங்களின் விகிதம் 3 : 4 ஆகும். ஒரு குறிப்பிட்ட தூரத்தைக் கடக்க B எடுத்துக் கொள்ளும் நேரம் 36 நிமிடங்கள் எனில், அதே தூரத்தைக் கடக்க A எடுத்துக் கொள்ளும் நேரம் எவ்வளவு?","options":["48 நிமிடங்கள்","27 நிமிடங்கள்","42 நிமிடங்கள்","54 நிமிடங்கள்"],"correctAnswer":0,"explanation":"குறிப்பிட்ட தூரத்திற்கு நேரமானது வேகத்திற்கு எதிர் விகிதத்தில் இருக்கும். வேக விகிதம் A : B = 3 : 4 என்பதால், நேர விகிதம் A : B = 4 : 3. இங்கு 3 பங்கு = 36 நிமிடங்கள் ⇒ 1 பங்கு = 12 நிமிடங்கள். எனவே A-யின் நேரம் = 4 × 12 = 48 நிமிடங்கள்.","difficulty":"easy","topic":"நேரம், வேகம் மற்றும் தூரம்"},{"id":776,"subject":"maths","testNumber":8,"question":"150 மீட்டர் நீளமுள்ள ஒரு ரயில் 54 கி.மீ/மணி வேகத்தில் சென்றால், வழியில் உள்ள ஒரு மின்கம்பத்தைக் கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["8 வினாடிகள்","12 வினாடிகள்","15 வினாடிகள்","10 வினாடிகள்"],"correctAnswer":3,"explanation":"ரயிலின் வேகம் = 54 × (5 / 18) = 15 மீ/வினாடி. மின்கம்பத்தைக் கடக்க ரயில் தன் நீளத்தைக் கடக்க வேண்டும். எனவே நேரம் = தூரம் / வேகம் = 150 / 15 = 10 வினாடிகள்.","difficulty":"easy","topic":"ரயில் கணக்குகள்"},{"id":777,"subject":"maths","testNumber":8,"question":"180 மீட்டர் நீளமுள்ள ரயில் 72 கி.மீ/மணி வேகத்தில் செல்கிறது. அது 220 மீட்டர் நீளமுள்ள நடைமேடையைக் கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["15 வினாடிகள்","18 வினாடிகள்","20 வினாடிகள்","25 வினாடிகள்"],"correctAnswer":2,"explanation":"வேகம் = 72 × (5 / 18) = 20 மீ/வினாடி. கடக்க வேண்டிய மொத்த தூரம் = ரயில் நீளம் + நடைமேடை நீளம் = 180 + 220 = 400 மீ. எனவே ஆகும் நேரம் = 400 / 20 = 20 வினாடிகள்.","difficulty":"easy","topic":"ரயில் கணக்குகள்"},{"id":778,"subject":"maths","testNumber":8,"question":"240 மீட்டர் நீளமுள்ள ஒரு ரயில் ஒரு சமிக்ஞை கம்பத்தை 12 வினாடிகளில் கடக்கிறது எனில், அந்த ரயிலின் வேகம் கி.மீ/மணியில் எவ்வளவு?","options":["60 கி.மீ/மணி","72 கி.மீ/மணி","80 கி.மீ/மணி","64 கி.மீ/மணி"],"correctAnswer":1,"explanation":"வேகம் (மீ/வினாடியில்) = 240 / 12 = 20 மீ/வினாடி. கி.மீ/மணியில் மாற்ற: 20 × (18 / 5) = 4 × 18 = 72 கி.மீ/மணி.","difficulty":"easy","topic":"ரயில் கணக்குகள்"},{"id":779,"subject":"maths","testNumber":8,"question":"90 கி.மீ/மணி வேகத்தில் செல்லும் ஒரு ரயில் 250 மீட்டர் நீளமுள்ள பாலத்தை 22 வினாடிகளில் கடக்கிறது எனில், அந்த ரயிலின் நீளம் எவ்வளவு?","options":["300 மீ","250 மீ","280 மீ","320 மீ"],"correctAnswer":0,"explanation":"வேகம் = 90 × (5 / 18) = 25 மீ/வினாடி. 22 வினாடிகளில் கடந்த மொத்த தூரம் = 25 × 22 = 550 மீ. இதில் பாலத்தின் நீளம் 250 மீ என்பதால், ரயிலின் நீளம் = 550 - 250 = 300 மீ.","difficulty":"easy","topic":"ரயில் கணக்குகள்"},{"id":780,"subject":"maths","testNumber":8,"question":"300 மீட்டர் நீளமுள்ள ரயில் ஒரு கம்பத்தை 15 வினாடிகளிலும், ஒரு சுரங்கப்பாதையை 40 வினாடிகளிலும் கடக்கிறது எனில், அந்தச் சுரங்கப்பாதையின் நீளம் எவ்வளவு?","options":["400 மீ","450 மீ","600 மீ","500 மீ"],"correctAnswer":3,"explanation":"ரயிலின் வேகம் = 300 / 15 = 20 மீ/வினாடி. 40 வினாடிகளில் கடந்த மொத்த தூரம் = 20 × 40 = 800 மீ. எனவே சுரங்கப்பாதையின் நீளம் = 800 - 300 = 500 மீ.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":781,"subject":"maths","testNumber":8,"question":"120 மீட்டர் நீளமுள்ள ரயில் 60 கி.மீ/மணி வேகத்தில் செல்கிறது. ரயில் செல்லும் அதே திசையில் 6 கி.மீ/மணி வேகத்தில் ஓடும் மனிதனை ரயில் கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["6 வினாடிகள்","7 வினாடிகள்","8 வினாடிகள்","10 வினாடிகள்"],"correctAnswer":2,"explanation":"ஒரே திசையில் சார்பு வேகம் = 60 - 6 = 54 கி.மீ/மணி = 54 × (5 / 18) = 15 மீ/வினாடி. மனிதனைக் கடக்க ஆகும் நேரம் = ரயில் நீளம் / சார்பு வேகம் = 120 / 15 = 8 வினாடிகள்.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":782,"subject":"maths","testNumber":8,"question":"150 மீட்டர் நீளமுள்ள ரயில் 68 கி.மீ/மணி வேகத்தில் செல்கிறது. எதிர் திசையில் 4 கி.மீ/மணி வேகத்தில் நடந்து வரும் மனிதனை ரயில் கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["6.5 வினாடிகள்","7.5 வினாடிகள்","8 வினாடிகள்","9 வினாடிகள்"],"correctAnswer":1,"explanation":"எதிர் திசையில் சார்பு வேகம் = 68 + 4 = 72 கி.மீ/மணி = 72 × (5 / 18) = 20 மீ/வினாடி. கடக்க ஆகும் நேரம் = 150 / 20 = 7.5 வினாடிகள்.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":783,"subject":"maths","testNumber":8,"question":"160 மீ மற்றும் 140 மீ நீளமுள்ள இரு ரயில்கள் எதிரெதிர் திசைகளில் முறையே 48 கி.மீ/மணி மற்றும் 60 கி.மீ/மணி வேகங்களில் சென்றால், அவை ஒன்றையொன்று கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["10 வினாடிகள்","12 வினாடிகள்","15 வினாடிகள்","8 வினாடிகள்"],"correctAnswer":0,"explanation":"மொத்த தூரம் = 160 + 140 = 300 மீ. எதிரெதிர் சார்பு வேகம் = 48 + 60 = 108 கி.மீ/மணி = 108 × (5 / 18) = 30 மீ/வினாடி. கடக்கும் நேரம் = 300 / 30 = 10 வினாடிகள்.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":784,"subject":"maths","testNumber":8,"question":"200 மீ மற்றும் 250 மீ நீளமுள்ள இரு ரயில்கள் ஒரே திசையில் முறையே 72 கி.மீ/மணி மற்றும் 54 கி.மீ/மணி வேகங்களில் சென்றால், வேகமான ரயில் மெதுவான ரயிலை முழுமையாகக் கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["60 வினாடிகள்","75 வினாடிகள்","80 வினாடிகள்","90 வினாடிகள்"],"correctAnswer":3,"explanation":"மொத்த தூரம் = 200 + 250 = 450 மீ. ஒரே திசையில் சார்பு வேகம் = 72 - 54 = 18 கி.மீ/மணி = 18 × (5 / 18) = 5 மீ/வினாடி. கடக்கும் நேரம் = 450 / 5 = 90 வினாடிகள்.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":785,"subject":"maths","testNumber":8,"question":"ஒரு ரயில் 800 மீ நீளமுள்ள பாலத்தை 100 வினாடிகளிலும், 400 மீ நீளமுள்ள பாலத்தை 60 வினாடிகளிலும் கடக்கிறது எனில், அந்த ரயிலின் நீளம் எவ்வளவு?","options":["150 மீ","250 மீ","200 மீ","300 மீ"],"correctAnswer":2,"explanation":"ரயிலின் வேகம் = தூர வித்தியாசம் / நேர வித்தியாசம் = (800 - 400) / (100 - 60) = 400 / 40 = 10 மீ/வினாடி. 60 வினாடிகளில் கடந்த தூரம் = 10 × 60 = 600 மீ. எனவே ரயிலின் நீளம் = 600 - 400 = 200 மீ.","difficulty":"hard","topic":"ரயில் கணக்குகள்"},{"id":786,"subject":"maths","testNumber":8,"question":"சம நீளமுள்ள இரு ரயில்கள் ஒரு மின்கம்பத்தை முறையே 10 வினாடிகள் மற்றும் 15 வினாடிகளில் கடக்கின்றன. அவை எதிரெதிர் திசைகளில் சென்றால் ஒன்றையொன்று கடக்க எத்தனை வினாடிகள் ஆகும்?","options":["10 வினாடிகள்","12 வினாடிகள்","12.5 வினாடிகள்","14 வினாடிகள்"],"correctAnswer":1,"explanation":"சம நீள ரயில்கள் எதிரெதிர் திசையில் ஒன்றையொன்று கடக்க ஆகும் நேரச் சூத்திரம் = (2 × t₁ × t₂) / (t₁ + t₂). இங்கு t₁ = 10, t₂ = 15. எனவே (2 × 10 × 15) / (10 + 15) = 300 / 25 = 12 வினாடிகள்.","difficulty":"hard","topic":"ரயில் கணக்குகள்"},{"id":787,"subject":"maths","testNumber":8,"question":"270 மீ நீளமுள்ள ஒரு ரயில் 120 கி.மீ/மணி வேகத்தில் செல்கிறது. எதிர் திசையில் 80 கி.மீ/மணி வேகத்தில் வரும் மற்றொரு ரயிலை 9 வினாடிகளில் கடக்கிறது எனில், இரண்டாவது ரயிலின் நீளம் எவ்வளவு?","options":["230 மீ","220 மீ","250 மீ","260 மீ"],"correctAnswer":0,"explanation":"எதிரெதிர் சார்பு வேகம் = 120 + 80 = 200 கி.மீ/மணி = 200 × (5 / 18) = 500/9 மீ/வினாடி. 9 வினாடிகளில் கடந்த மொத்த தூரம் = (500 / 9) × 9 = 500 மீ. எனவே இரண்டாவது ரயிலின் நீளம் = 500 - 270 = 230 மீ.","difficulty":"hard","topic":"ரயில் கணக்குகள்"},{"id":788,"subject":"maths","testNumber":8,"question":"180 மீ நீளமுள்ள ஒரு ரயில் ஒரே திசையில் 10 கி.மீ/மணி வேகத்தில் ஓடும் மனிதனை 12 வினாடிகளில் கடக்கிறது எனில், அந்த ரயிலின் வேகம் கி.மீ/மணியில் எவ்வளவு?","options":["54 கி.மீ/மணி","60 கி.மீ/மணி","68 கி.மீ/மணி","64 கி.மீ/மணி"],"correctAnswer":3,"explanation":"சார்பு வேகம் = 180 / 12 = 15 மீ/வினாடி = 15 × (18 / 5) = 54 கி.மீ/மணி. ஒரே திசை என்பதால் ரயிலின் வேகம் - மனிதனின் வேகம் = 54 ⇒ ரயிலின் வேகம் = 54 + 10 = 64 கி.மீ/மணி.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":789,"subject":"maths","testNumber":8,"question":"ஒரு ரயில் 50 மீட்டர் நீளமுள்ள நடைமேடையை 14 வினாடிகளிலும், நடைமேடையில் நிற்கும் மனிதனை 10 வினாடிகளிலும் கடக்கிறது எனில், ரயிலின் வேகம் கி.மீ/மணியில் எவ்வளவு?","options":["36 கி.மீ/மணி","40 கி.மீ/மணி","45 கி.மீ/மணி","54 கி.மீ/மணி"],"correctAnswer":2,"explanation":"நடைமேடையின் 50 மீ நீளத்தைக் கடக்க ரயில் எடுத்துக் கொண்ட கூடுதல் நேரம் = 14 - 10 = 4 வினாடிகள். எனவே ரயிலின் வேகம் = 50 / 4 = 12.5 மீ/வினாடி. கி.மீ/மணியில்: 12.5 × (18 / 5) = 2.5 × 18 = 45 கி.மீ/மணி.","difficulty":"medium","topic":"ரயில் கணக்குகள்"},{"id":790,"subject":"maths","testNumber":8,"question":"நிலைநீரில் ஒரு படகின் வேகம் 12 கி.மீ/மணி மற்றும் நீரோட்டத்தின் வேகம் 3 கி.மீ/மணி எனில், நீரோட்டத் திசையில் 45 கி.மீ தூரத்தைக் கடக்க எத்தனை மணி நேரம் ஆகும்?","options":["2.5 மணி","3 மணி","3.5 மணி","5 மணி"],"correctAnswer":1,"explanation":"நீரோட்டத் திசை வேகம் (Downstream) = u + v = 12 + 3 = 15 கி.மீ/மணி. எனவே 45 கி.மீ தூரத்தைக் கடக்க ஆகும் நேரம் = 45 / 15 = 3 மணி.","difficulty":"easy","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":791,"subject":"maths","testNumber":8,"question":"நிலைநீரில் ஒரு படகின் வேகம் 15 கி.மீ/மணி மற்றும் நீரோட்டத்தின் வேகம் 5 கி.மீ/மணி எனில், நீரோட்டத்திற்கு எதிர் திசையில் 40 கி.மீ தூரத்தைக் கடக்க எத்தனை மணி நேரம் ஆகும்?","options":["4 மணி","2 மணி","3 மணி","5 மணி"],"correctAnswer":0,"explanation":"நீரோட்ட எதிர் திசை வேகம் (Upstream) = u - v = 15 - 5 = 10 கி.மீ/மணி. எனவே 40 கி.மீ தூரத்தைக் கடக்க ஆகும் நேரம் = 40 / 10 = 4 மணி.","difficulty":"easy","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":792,"subject":"maths","testNumber":8,"question":"ஒரு படகு நீரோட்டத் திசையில் 16 கி.மீ/மணி வேகத்திலும், எதிர் திசையில் 10 கி.மீ/மணி வேகத்திலும் செல்கிறது எனில், நிலைநீரில் படகின் வேகம் எவ்வளவு?","options":["11 கி.மீ/மணி","12 கி.மீ/மணி","14 கி.மீ/மணி","13 கி.மீ/மணி"],"correctAnswer":3,"explanation":"சூத்திரம்: நிலைநீரில் படகின் வேகம் u = (நீரோட்டத் திசை வேகம் + எதிர் திசை வேகம்) / 2 = (16 + 10) / 2 = 26 / 2 = 13 கி.மீ/மணி.","difficulty":"easy","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":793,"subject":"maths","testNumber":8,"question":"ஒரு படகு நீரோட்டத் திசையில் 21 கி.மீ/மணி வேகத்திலும், எதிர் திசையில் 13 கி.மீ/மணி வேகத்திலும் செல்கிறது எனில், நீரோட்டத்தின் வேகம் எவ்வளவு?","options":["3 கி.மீ/மணி","3.5 கி.மீ/மணி","4 கி.மீ/மணி","5 கி.மீ/மணி"],"correctAnswer":2,"explanation":"சூத்திரம்: நீரோட்டத்தின் வேகம் v = (நீரோட்டத் திசை வேகம் - எதிர் திசை வேகம்) / 2 = (21 - 13) / 2 = 8 / 2 = 4 கி.மீ/மணி.","difficulty":"easy","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":794,"subject":"maths","testNumber":8,"question":"ஒரு படகு நீரோட்டத் திசையில் 24 கி.மீ தூரத்தை 2 மணி நேரத்திலும், எதிர் திசையில் 16 கி.மீ தூரத்தை 2 மணி நேரத்திலும் கடக்கிறது எனில், நிலைநீரில் படகின் வேகம் எவ்வளவு?","options":["8 கி.மீ/மணி","10 கி.மீ/மணி","11 கி.மீ/மணி","12 கி.மீ/மணி"],"correctAnswer":1,"explanation":"நீரோட்டத் திசை வேகம் D = 24 / 2 = 12 கி.மீ/மணி. எதிர் திசை வேகம் U = 16 / 2 = 8 கி.மீ/மணி. எனவே நிலைநீரில் படகின் வேகம் = (12 + 8) / 2 = 10 கி.மீ/மணி.","difficulty":"easy","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":795,"subject":"maths","testNumber":8,"question":"ஒரு நீச்சல் வீரர் நீரோட்டத் திசையில் 36 கி.மீ தூரத்தை 3 மணி நேரத்திலும், எதிர் திசையில் 24 கி.மீ தூரத்தை 4 மணி நேரத்திலும் நீந்துகிறார் எனில், நீரோட்டத்தின் வேகம் எவ்வளவு?","options":["3 கி.மீ/மணி","2 கி.மீ/மணி","4 கி.மீ/மணி","4.5 கி.மீ/மணி"],"correctAnswer":0,"explanation":"நீரோட்டத் திசை வேகம் D = 36 / 3 = 12 கி.மீ/மணி. எதிர் திசை வேகம் U = 24 / 4 = 6 கி.மீ/மணி. எனவே நீரோட்டத்தின் வேகம் = (12 - 6) / 2 = 3 கி.மீ/மணி.","difficulty":"easy","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":796,"subject":"maths","testNumber":8,"question":"நிலைநீரில் ஒரு படகின் வேகம் 10 கி.மீ/மணி மற்றும் நீரோட்டத்தின் வேகம் 2 கி.மீ/மணி. ஒரு இடத்திற்குச் சென்று மீண்டும் புறப்பட்ட இடத்திற்குத் திரும்ப மொத்தம் 5 மணி நேரம் ஆகிறது எனில், அந்த இடத்தின் தூரம் எவ்வளவு?","options":["18 கி.மீ","20 கி.மீ","22 கி.மீ","24 கி.மீ"],"correctAnswer":3,"explanation":"நீரோட்டத் திசை வேகம் = 10 + 2 = 12 கி.மீ/மணி; எதிர் திசை வேகம் = 10 - 2 = 8 கி.மீ/மணி. தூரம் d என்க: d/12 + d/8 = 5 ⇒ (2d + 3d)/24 = 5 ⇒ 5d = 120 ⇒ d = 24 கி.மீ.","difficulty":"medium","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":797,"subject":"maths","testNumber":8,"question":"நிலைநீரில் ஒரு படகின் வேகம் 9 கி.மீ/மணி மற்றும் நீரோட்டத்தின் வேகம் 3 கி.மீ/மணி. A-யிலிருந்து B-க்கு 36 கி.மீ தூரம் சென்று மீண்டும் A-க்குத் திரும்ப மொத்தம் எவ்வளவு நேரம் ஆகும்?","options":["7 மணி","8 மணி","9 மணி","10 மணி"],"correctAnswer":2,"explanation":"நீரோட்டத் திசை வேகம் = 9 + 3 = 12 கி.மீ/மணி ⇒ ஆகும் நேரம் = 36 / 12 = 3 மணி. எதிர் திசை வேகம் = 9 - 3 = 6 கி.மீ/மணி ⇒ ஆகும் நேரம் = 36 / 6 = 6 மணி. மொத்த நேரம் = 3 + 6 = 9 மணி.","difficulty":"medium","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":798,"subject":"maths","testNumber":8,"question":"ஒரு படகு ஒரு குறிப்பிட்ட தூரத்தை நீரோட்டத் திசையில் கடக்க எடுத்துக் கொள்ளும் நேரத்தை விட, எதிர் திசையில் கடக்க இரு மடங்கு நேரம் எடுத்துக் கொள்கிறது. நீரோட்டத்தின் வேகம் 4 கி.மீ/மணி எனில், நிலைநீரில் படகின் வேகம் எவ்வளவு?","options":["8 கி.மீ/மணி","12 கி.மீ/மணி","14 கி.மீ/மணி","16 கி.மீ/மணி"],"correctAnswer":1,"explanation":"நேர விகிதம் எதிர் : நீரோட்டம் = 2 : 1 என்பதால், வேக விகிதம் (u + v) / (u - v) = 2 / 1. இங்கு v = 4. எனவே (u + 4) / (u - 4) = 2 ⇒ u + 4 = 2u - 8 ⇒ u = 12 கி.மீ/மணி.","difficulty":"medium","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":799,"subject":"maths","testNumber":8,"question":"நிலைநீரில் ஒரு படகின் வேகம் 15 கி.மீ/மணி. அது நீரோட்டத் திசையில் 30 கி.மீ சென்று மீண்டும் புறப்பட்ட இடத்திற்குத் திரும்ப மொத்தம் 4 மணி 30 நிமிடங்கள் ஆகிறது எனில், நீரோட்டத்தின் வேகம் எவ்வளவு?","options":["5 கி.மீ/மணி","4 கி.மீ/மணி","6 கி.மீ/மணி","3 கி.மீ/மணி"],"correctAnswer":0,"explanation":"நீரோட்ட வேகம் = v என்க. 30/(15 + v) + 30/(15 - v) = 4.5 = 9/2. சுருக்க: 30 × 30 / (225 - v²) = 9/2 ⇒ 900 / (225 - v²) = 9/2 ⇒ 225 - v² = 200 ⇒ v² = 25 ⇒ v = 5 கி.மீ/மணி.","difficulty":"hard","topic":"படகு மற்றும் நீரோடை கணக்குகள்"},{"id":800,"subject":"maths","testNumber":8,"question":"ஒரு படகு நீரோட்டத் திசையில் 48 கி.மீ மற்றும் எதிர் திசையில் 30 கி.மீ செல்ல 9 மணி நேரமும்; நீரோட்டத் திசையில் 60 கி.மீ மற்றும் எதிர் திசையில் 42 கி.மீ செல்ல 12 மணி நேரமும் எடுத்துக் கொள்கிறது எனில், நிலைநீரில் படகின் வேகம் எவ்வளவு?","options":["8 கி.மீ/மணி","10 கி.மீ/மணி","12 கி.மீ/மணி","9 கி.மீ/மணி"],"correctAnswer":3,"explanation":"1/D = a மற்றும் 1/U = b என்க. சமன்பாடுகள்: 48a + 30b = 9 ⇒ 16a + 10b = 3 ... (1); 60a + 42b = 12 ⇒ 10a + 7b = 2 ... (2). (1)×5 ⇒ 80a + 50b = 15; (2)×8 ⇒ 80a + 56b = 16. கழிக்க: 6b = 1 ⇒ b = 1/6 (U = 6 கி.மீ/மணி). இதைப் பிரதியிட a = 1/12 (D = 12 கி.மீ/மணி). எனவே நிலைநீரில் படகின் வேகம் u = (12 + 6) / 2 = 9 கி.மீ/மணி.","difficulty":"hard","topic":"படகு மற்றும் நீரோடை கணக்குகள்"}]);
